BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '120s';
CREATE TEMP TABLE _approved_302 (
 master_id integer PRIMARY KEY,
 canonical_id text NOT NULL,
 provider_id text NOT NULL,
 source_row_id integer NOT NULL,
 source_url text NOT NULL,
 latitude double precision NOT NULL,
 longitude double precision NOT NULL,
 official_x double precision NOT NULL,
 official_y double precision NOT NULL,
 official_attributes jsonb NOT NULL,
 evidence_reference text NOT NULL,
 approval_status text NOT NULL
) ON COMMIT DROP;
DO $precheck$
DECLARE v_bad integer; v_count integer; v_duplicates integer;
BEGIN
 SELECT count(*) INTO v_count FROM _approved_302;
 IF v_count <> 302 THEN RAISE EXCEPTION 'ALLOWLIST_COUNT expected=302 actual=%',v_count; END IF;
 IF (SELECT count(DISTINCT provider_id) FROM _approved_302) <> 302 THEN RAISE EXCEPTION 'DUPLICATE_PROVIDER_IDS'; END IF;
 IF EXISTS (SELECT 1 FROM _approved_302 WHERE approval_status IS DISTINCT FROM 'APPROVED_FOR_GEOGRAPHIC_CORRECTION' OR evidence_reference IS NULL OR evidence_reference='' OR source_url NOT LIKE 'https://%') THEN RAISE EXCEPTION 'APPROVAL_OR_EVIDENCE_REFERENCE_INVALID'; END IF;
 SELECT count(*) INTO v_bad
 FROM _approved_302 a
 LEFT JOIN opportunities o ON o.id=a.master_id
 LEFT JOIN geographic_reference_units g ON g.id=o.geography_reference_unit_id
 LEFT JOIN geographic_reference_units pg ON pg.id=g.parent_id
 LEFT JOIN source_opportunities so ON so.id=a.source_row_id
 LEFT JOIN sources s ON s.id=so.source_id
 WHERE o.id IS NULL OR o.merged_into_id IS NOT NULL
    OR o.canonical_id IS DISTINCT FROM a.canonical_id
    OR o.geographic_scope IS DISTINCT FROM 'UNSPECIFIED'
    OR o.manual_review_required IS TRUE
    OR o.latitude IS DISTINCT FROM a.latitude OR o.longitude IS DISTINCT FROM a.longitude
    OR g.level IS DISTINCT FROM 'governorate' OR g.external_id IS DISTINCT FROM '501' OR pg.external_id IS DISTINCT FROM '5'
    OR so.id IS NULL OR s.source_key IS DISTINCT FROM 'furas'
    OR so.master_opportunity_id IS DISTINCT FROM a.master_id
    OR so.source_opportunity_id IS DISTINCT FROM a.provider_id
    OR so.source_url IS DISTINCT FROM a.source_url
    OR so.raw_data_json->'attributes'->>'OPPORTUNITYID' IS DISTINCT FROM a.provider_id
    OR (so.raw_data_json->'geometry'->>'y')::double precision IS DISTINCT FROM a.latitude
    OR (so.raw_data_json->'geometry'->>'x')::double precision IS DISTINCT FROM a.longitude
    OR o.coordinate_provenance_json->>'verified' IS DISTINCT FROM 'true'
    OR o.coordinate_provenance_json->>'verification_method' IS DISTINCT FROM 'DIRECT_SOURCE_COORDINATE'
    OR o.coordinate_provenance_json->>'source_record_identity_matches' IS DISTINCT FROM 'true'
    OR (o.coordinate_provenance_json->>'source_record_id')::integer IS DISTINCT FROM a.source_row_id
    OR o.coordinate_provenance_json->>'source_opportunity_id' IS DISTINCT FROM a.provider_id
    OR (o.coordinate_provenance_json->>'source_latitude')::double precision IS DISTINCT FROM a.latitude
    OR (o.coordinate_provenance_json->>'source_longitude')::double precision IS DISTINCT FROM a.longitude
    OR o.coordinate_provenance_json#>>'{boundary_validation,status}' IS DISTINCT FROM 'VERIFIED_IN_SAUDI'
    OR o.coordinate_provenance_json#>>'{boundary_validation,method}' IS DISTINCT FROM 'POINT_IN_OFFICIAL_REGION_POLYGON'
    OR abs(a.official_x-a.longitude)>1e-7 OR abs(a.official_y-a.latitude)>1e-7
    OR (so.raw_data_json->'attributes'->>'AMANA') IS DISTINCT FROM (a.official_attributes->>'AMANA')
    OR (so.raw_data_json->'attributes'->>'BALADYA') IS DISTINCT FROM (a.official_attributes->>'BALADYA')
    OR (so.raw_data_json->'attributes'->>'CITY_ID') IS DISTINCT FROM (a.official_attributes->>'CITY_ID')
    OR (so.raw_data_json->'attributes'->>'CITYNAME') IS DISTINCT FROM (a.official_attributes->>'CITYNAME')
    OR (so.raw_data_json->'attributes'->>'REGION_ID') IS DISTINCT FROM (a.official_attributes->>'REGION_ID')
    OR (so.raw_data_json->'attributes'->>'REGIONNAME') IS DISTINCT FROM (a.official_attributes->>'REGIONNAME')
    OR (SELECT count(*) FROM source_opportunities s2 JOIN sources ss2 ON ss2.id=s2.source_id WHERE s2.master_opportunity_id=a.master_id AND ss2.source_key='furas') <> 1
    OR (SELECT count(*) FROM source_opportunities sx JOIN sources ssx ON ssx.id=sx.source_id WHERE ssx.source_key='furas' AND sx.source_opportunity_id=a.provider_id) <> 1
    OR EXISTS (SELECT 1 FROM opportunity_data_conflicts c WHERE c.opportunity_id=a.master_id AND c.status IN ('OPEN','PENDING'))
    OR EXISTS (SELECT 1 FROM location_reviews lr WHERE lr.source_record_id=a.source_row_id AND lr.status IN ('OPEN','PENDING'));
 IF v_bad <> 0 THEN RAISE EXCEPTION 'LIVE_302_REVALIDATION_FAILURE rows=%',v_bad; END IF;
 SELECT count(*) INTO v_bad FROM (SELECT master_id FROM _approved_302 GROUP BY master_id HAVING count(*)<>1) d;
 IF v_bad <> 0 THEN RAISE EXCEPTION 'DUPLICATE_MASTER_IDS'; END IF;
 SELECT count(*) INTO v_bad FROM source_sync_jobs WHERE status IN ('QUEUED','PENDING','RUNNING','RETRYING');
 IF v_bad <> 0 THEN RAISE EXCEPTION 'ACTIVE_SYNC_JOB_COUNT=%',v_bad; END IF;
 SELECT count(*) INTO v_bad FROM _approved_302 a JOIN source_opportunities so ON so.id=a.source_row_id JOIN sources s ON s.id=so.source_id WHERE s.source_key='furas' AND a.master_id=64;
 IF v_bad <> 0 THEN RAISE EXCEPTION 'HELD_MASTER_64_IN_TARGET_SET'; END IF;
END
$precheck$;
CREATE TEMP TABLE _protected_before ON COMMIT DROP AS
SELECT o.id AS master_id,to_jsonb(o) AS row_json
FROM opportunities o JOIN geographic_reference_units g ON g.id=o.geography_reference_unit_id
WHERE o.merged_into_id IS NULL AND g.level='governorate' AND g.external_id='501';
CREATE TEMP TABLE _source_before ON COMMIT DROP AS
SELECT so.id AS source_row_id,to_jsonb(so) AS row_json,
       (SELECT count(*) FROM source_observations ob WHERE ob.source_opportunity_id=so.id) AS observations_count
FROM source_opportunities so JOIN _approved_302 a ON a.source_row_id=so.id;
CREATE TEMP TABLE _global_before ON COMMIT DROP AS
SELECT (SELECT count(*) FROM opportunities) AS masters,
       (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL) AS nonmerged,
       (SELECT count(*) FROM source_opportunities) AS source_opportunities,
       (SELECT count(*) FROM source_observations) AS source_observations,
       (SELECT count(*) FROM opportunity_change_history) AS opportunity_change_history,
       (SELECT count(*) FROM audit_events) AS audit_events,
       (SELECT count(*) FROM source_identity_aliases) AS aliases,
       (SELECT count(*) FROM source_identity_alias_audits) AS alias_audits,
       (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope='SPECIFIC_LOCATION') AS specific_scope,
       (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope='UNSPECIFIED') AS unspecified_scope,
       (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope IS NULL) AS null_scope;
CREATE TEMP TABLE _geography_before ON COMMIT DROP AS
SELECT (SELECT count(*) FROM geographic_reference_datasets) AS dataset_count,
       (SELECT count(*) FROM geographic_reference_units) AS unit_count,
       (SELECT md5(coalesce(string_agg(to_jsonb(d)::text,E'\n' ORDER BY d.id),'')) FROM geographic_reference_datasets d) AS dataset_sha,
       (SELECT md5(coalesce(string_agg(to_jsonb(u)::text,E'\n' ORDER BY u.id),'')) FROM geographic_reference_units u) AS unit_sha;
DO $lock$
DECLARE v_locked integer; v_source_locked integer;
BEGIN
 IF (SELECT count(*) FROM _protected_before) <> 518 THEN RAISE EXCEPTION 'PROTECTED_ALAHSA_SNAPSHOT expected=518 actual=%',(SELECT count(*) FROM _protected_before); END IF;
 PERFORM o.id FROM opportunities o JOIN _approved_302 a ON a.master_id=o.id ORDER BY o.id FOR UPDATE OF o;
 GET DIAGNOSTICS v_locked = ROW_COUNT;
 IF v_locked <> 302 THEN RAISE EXCEPTION 'MASTER_LOCK_COUNT expected=302 actual=%',v_locked; END IF;
 PERFORM so.id FROM source_opportunities so JOIN _approved_302 a ON a.source_row_id=so.id ORDER BY so.id FOR UPDATE OF so;
 GET DIAGNOSTICS v_source_locked = ROW_COUNT;
 IF v_source_locked <> 302 THEN RAISE EXCEPTION 'SOURCE_LOCK_COUNT expected=302 actual=%',v_source_locked; END IF;
END
$lock$;
CREATE TEMP TABLE _updated_master_ids(master_id integer PRIMARY KEY) ON COMMIT DROP;
WITH changed AS (
 UPDATE opportunities o SET geographic_scope='SPECIFIC_LOCATION'
 FROM _approved_302 a
 WHERE o.id=a.master_id AND o.geographic_scope='UNSPECIFIED'
 RETURNING o.id
)
DO $postcheck$
DECLARE v_bad integer; v_updated integer;
BEGIN
 SELECT count(*) INTO v_updated FROM _updated_master_ids;
 IF v_updated <> 302 THEN RAISE EXCEPTION 'UPDATE_COUNT expected=302 actual=%',v_updated; END IF;
 SELECT count(*) INTO v_bad FROM _approved_302 a JOIN opportunities o ON o.id=a.master_id
 WHERE o.geographic_scope IS DISTINCT FROM 'SPECIFIC_LOCATION';
 IF v_bad <> 0 THEN RAISE EXCEPTION 'NEW_SCOPE_CHECK_FAILURE rows=%',v_bad; END IF;
 SELECT count(*) INTO v_bad FROM _protected_before b LEFT JOIN opportunities o ON o.id=b.master_id
 LEFT JOIN _approved_302 a ON a.master_id=b.master_id
 WHERE o.id IS NULL OR (a.master_id IS NULL AND to_jsonb(o) IS DISTINCT FROM b.row_json)
       OR (a.master_id IS NOT NULL AND (to_jsonb(o)-'geographic_scope') IS DISTINCT FROM (b.row_json-'geographic_scope'));
 IF v_bad <> 0 THEN RAISE EXCEPTION 'PROTECTED_ALAHSA_FIELD_CHANGE rows=%',v_bad; END IF;
 SELECT count(*) INTO v_bad FROM _source_before b JOIN source_opportunities so ON so.id=b.source_row_id
 WHERE to_jsonb(so) IS DISTINCT FROM b.row_json
    OR (SELECT count(*) FROM source_observations ob WHERE ob.source_opportunity_id=so.id) IS DISTINCT FROM b.observations_count;
 IF v_bad <> 0 OR (SELECT count(*) FROM _source_before) <> 302 THEN RAISE EXCEPTION 'SOURCE_IDENTITY_OR_OBSERVATION_CHANGED rows=%',v_bad; END IF;
 SELECT count(*) INTO v_bad FROM _global_before b
 WHERE b.masters IS DISTINCT FROM (SELECT count(*) FROM opportunities)
    OR b.nonmerged IS DISTINCT FROM (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL)
    OR b.source_opportunities IS DISTINCT FROM (SELECT count(*) FROM source_opportunities)
    OR b.source_observations IS DISTINCT FROM (SELECT count(*) FROM source_observations)
    OR b.opportunity_change_history IS DISTINCT FROM (SELECT count(*) FROM opportunity_change_history)
    OR b.audit_events IS DISTINCT FROM (SELECT count(*) FROM audit_events)
    OR b.aliases IS DISTINCT FROM (SELECT count(*) FROM source_identity_aliases)
    OR b.alias_audits IS DISTINCT FROM (SELECT count(*) FROM source_identity_alias_audits)
    OR (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope='SPECIFIC_LOCATION') <> b.specific_scope+302
    OR (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope='UNSPECIFIED') <> b.unspecified_scope-302
    OR (SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope IS NULL) <> b.null_scope;
 IF v_bad <> 0 THEN RAISE EXCEPTION 'GLOBAL_OR_SCOPE_DISTRIBUTION_CHECK_FAILURE'; END IF;
 SELECT count(*) INTO v_bad FROM _geography_before b
 WHERE b.dataset_count IS DISTINCT FROM (SELECT count(*) FROM geographic_reference_datasets)
    OR b.unit_count IS DISTINCT FROM (SELECT count(*) FROM geographic_reference_units)
    OR b.dataset_sha IS DISTINCT FROM (SELECT md5(coalesce(string_agg(to_jsonb(d)::text,E'\n' ORDER BY d.id),'')) FROM geographic_reference_datasets d)
    OR b.unit_sha IS DISTINCT FROM (SELECT md5(coalesce(string_agg(to_jsonb(u)::text,E'\n' ORDER BY u.id),'')) FROM geographic_reference_units u);
 IF v_bad <> 0 THEN RAISE EXCEPTION 'GEOGRAPHIC_REFERENCE_CHANGED'; END IF;
 SELECT count(*) INTO v_bad FROM source_sync_jobs WHERE status IN ('QUEUED','PENDING','RUNNING','RETRYING');
 IF v_bad <> 0 THEN RAISE EXCEPTION 'SYNC_JOB_ACTIVE_DURING_TRANSACTION=%',v_bad; END IF;
 IF (SELECT version_num FROM alembic_version) IS DISTINCT FROM '0026_source_identity_aliases' THEN RAISE EXCEPTION 'MIGRATION_HEAD_CHANGED'; END IF;
END
$postcheck$;
SELECT jsonb_build_object('status','PRECOMMIT_GUARDS_PASSED','transaction_id',txid_current()::text,'isolation',current_setting('transaction_isolation'),'updated_rows',(SELECT count(*) FROM _updated_master_ids),'protected_al_ahsa_rows',(SELECT count(*) FROM _protected_before),'source_rows_guarded',(SELECT count(*) FROM _source_before),'scope_distribution_after',jsonb_build_object('SPECIFIC_LOCATION',(SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope='SPECIFIC_LOCATION'),'UNSPECIFIED',(SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope='UNSPECIFIED'),'NULL',(SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL AND geographic_scope IS NULL)),'source_counts_after',jsonb_build_object('masters',(SELECT count(*) FROM opportunities),'nonmerged',(SELECT count(*) FROM opportunities WHERE merged_into_id IS NULL),'source_opportunities',(SELECT count(*) FROM source_opportunities),'source_observations',(SELECT count(*) FROM source_observations)),'production_mutations',302,'changed_field','opportunities.geographic_scope')::text AS transaction_audit;
COMMIT;
